function toStudioBranchRef(input: { repo: string | null; branch: string | null } | null | undefined): StudioBranchRef | null {
  if ("'!input?.repo || !input.branch) {
    return null;
  }
  return {
    repo: input.repo,
    branch: input.branch,
  };
}

function branchRefKey(branch: StudioBranchRef): string {
