 44	export function clampAuthoritativeDiffSnapshot(value: unknown, maxBytes: number): unknown {
 45	  const record = asRecord(value);
 46	  if (Object.keys(record).length === 0) {
 47	    return value;
 48	  }
 49	
 50	  const patch = typeof record.patch === 'string' ? record.patch : null;
 51	  if (!patch) {
 52	    return value;
 53	  }
 54	
 55	  const clamped = clampText(patch, maxBytes);
 56	  return {
 57	    ...record,
 58	    patch: clamped.text,
 59	    truncated: clamped.truncated || Boolean(record.truncated),
 60	  };
 61	}
