   216	    }),
   217	  });
   218	
   219	  if (!response.ok) {
   220	    await throwWorkerError(response);
   221	  }
   222	
   223	  if (!response.body) {
   224	    const bodyText = await response.text();
   225	    for (const event of parseSseChunk(bodyText)) {
   226	      await onEvent(event);
   227	    }
   228	    return;
   229	  }
   230	
   231	  const decoder = new TextDecoder();
   232	  const reader = response.body.getReader();
   233	  let buffer = '';
   234	
   235	  while (true) {
   236	    const { done, value } = await reader.read();
   237	    if (done) {
   238	      break;
   239	    }
   240	
   241	    buffer += decoder.decode(value, { stream: true });
   242	    const parts = buffer.split('\n\n');
   243	    buffer = parts.pop() ?? '';
   244	    for (const part of parts) {
   245	      for (const event of parseSseChunk(part)) {
   246	        await onEvent(event);
   247	      }
   248	    }
