  if (!hasToolOutput(history, 'diff_summary')) {
    return { type: 'tool', tool: 'diff_summary', args: { maxBytes: 32_000 } };
  }
  if (!hasToolOutput(history, 'list_files')) {
    return { type: 'tool', tool: 'list_files', args: { path: '.' } };
  }
  return {
    type: 'final',
